INSERT INTO public.reception_quiz (mavzu, test_id, question_text, option_text, option_image, is_correct) VALUES ('1-mavzu', '1-test', 'Reseption xodimining asosiy professional roli qaysi javobda to‘g‘ri ifodalangan?', 'A) Mehmonni faqat ro‘yxatdan o‘tkazish va kalit berish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/IMG_4318.PNG', false),('1-mavzu', '1-test', 'Reseption xodimining asosiy professional roli qaysi javobda to‘g‘ri ifodalangan?', 'B) Mehmon bilan ilk aloqa o‘rnatib, ishonch va ijobiy taassurot yaratish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.b.png', true),('1-mavzu', '1-test', 'Reseption xodimining asosiy professional roli qaysi javobda to‘g‘ri ifodalangan?', 'C) Mehmonxona ichki hujjatlari bilan ishlash', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.c.png', false),('1-mavzu', '1-test', 'Reseption xodimining asosiy professional roli qaysi javobda to‘g‘ri ifodalangan?', 'D) Faqat menejer topshiriqlarini bajarish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.d.png', false),('1-mavzu', '2-test', 'Nima sababdan reseption xodimi mehmonxona obro‘siga bevosita ta’sir qiladi?', 'A) Chunki u xizmat narxlarini belgilaydi', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.2.a.png', false),('1-mavzu', '2-test', 'Nima sababdan reseption xodimi mehmonxona obro‘siga bevosita ta’sir qiladi?', 'B) Chunki u mehmon bilan eng ko‘p muloqot qiladigan xodim', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.2.b.png', true),('1-mavzu', '2-test', 'Nima sababdan reseption xodimi mehmonxona obro‘siga bevosita ta’sir qiladi?', 'C) Chunki u xonalarni tayyorlaydi', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.2.c.png', false),('1-mavzu', '2-test', 'Nima sababdan reseption xodimi mehmonxona obro‘siga bevosita ta’sir qiladi?', 'D) Chunki faqat u doimo ish bilan band bo‘ladi', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.2.d.png', false),('1-mavzu', '3-test', 'Quyidagi holatlardan qaysi biri reseption xodimining professional mas’uliyatiga kiradi?', 'A) Mehmon murojaatini diqqat bilan eshitish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.3.a.png', true),('1-mavzu', '3-test', 'Quyidagi holatlardan qaysi biri reseption xodimining professional mas’uliyatiga kiradi?', 'B) Mehmon oldida shaxsiy telefon bilan shug‘ullanish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.3.b.png', false),('1-mavzu', '3-test', 'Quyidagi holatlardan qaysi biri reseption xodimining professional mas’uliyatiga kiradi?', 'C) Mehmonni kutishga va qaror qilishga majbur qilish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.3.c.png', false),('1-mavzu', '3-test', 'Quyidagi holatlardan qaysi biri reseption xodimining professional mas’uliyatiga kiradi?', 'D) Ikkinchi darajali muammolarni e’tiborsiz qoldirish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.3.d.png', false),('1-mavzu', '4-test', 'Mehmon shikoyat bilan murojaat qilganida reseption xodimi qanday yondashuvni tanlashi kerak?', 'A) Qoidalarni qat’iy aytib, suhbatni tez tugatish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.4.a.png', false),('1-mavzu', '4-test', 'Mehmon shikoyat bilan murojaat qilganida reseption xodimi qanday yondashuvni tanlashi kerak?', 'B) Mehmonni boshqa kerakli bo‘limga yuborish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.4.b.png', false),('1-mavzu', '4-test', 'Mehmon shikoyat bilan murojaat qilganida reseption xodimi qanday yondashuvni tanlashi kerak?', 'C) Xotirjam, hurmat bilan eshitib, yechim izlash va taqdim etish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.4.c.png', true),('1-mavzu', '4-test', 'Mehmon shikoyat bilan murojaat qilganida reseption xodimi qanday yondashuvni tanlashi kerak?', 'D) Javob bermasdan menejerni kutish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-1/1.4.d.png', false),('1-mavzu', '